export function Counter() {
  const [count, setCount] = useState(0);

  const handleIncrement = () => {
    setCount((prevCount) => prevCount + 1);
  };

  return (
    <button onClick={handleIncrement} className="btn-primary">
      Completed Lessons: {count}
    </button>
  );
}

